LANGS = ["en", "hi", "mr"]

def build_report(lang):
    blocks = []
    def add(section, tag_key, key, **kwargs):
        text = T[key][lang].format(**kwargs) if key in T else kwargs.get("text", "")
        blocks.append({
            "section": section, "tag_key": tag_key,
            "tag_label": TAG_LABELS[lang][tag_key], "text": text,
        })

    n_people = len(dataset["people"]); n_calls = len(dataset["calls"]); n_txn = len(dataset["transactions"])
    add(1, "FACT", "persons_identified", n=n_people)
    add(1, "FACT", "records_ingested", calls=n_calls, txn=n_txn)
    add(1, "AI_INFERENCE", "resolution_reduced", n=len(resolution))

    for r in resolution:
        pct = round(r["confidence"] * 100)
        if r["confidence"] >= 0.60:
            add(2, "AI_INFERENCE", "resolved_merge", mention=r["mention"], source=r["source_doc"], name=r["matched_person_name"], pct=pct)
        elif r["confidence"] >= 0.40:
            add(2, "LEAD", "resolved_review", mention=r["mention"], source=r["source_doc"], name=r["matched_person_name"], pct=pct)
        else:
            add(2, "FACT", "resolved_none", mention=r["mention"], source=r["source_doc"])

    add(3, "FACT", "graph_summary", nodes=len(graph["nodes"]), edges=len(graph["edges"]))
    add(3, "AI_INFERENCE", "communities_found", n=len(graph["communities"]))
    id_to_label = {n["id"]: n["label"] for n in graph["nodes"]}
    for pid in graph["priority_ranking"][:3]:
        add(3, "AI_INFERENCE", "priority_entity", name=id_to_label.get(pid, pid))
    if graph.get("shortest_path_example"):
        path_labels = " \u2192 ".join(id_to_label.get(n, n) for n in graph["shortest_path_example"])
        add(3, "AI_INFERENCE", "shortest_path", path=path_labels)
        add(3, "LEAD", "verify_indirect")

    for r in risk[:5]:
        b = r["breakdown"]
        add(4, "AI_INFERENCE", "risk_line", name=r["name"], score=r["risk_indicator_score"],
            ca=b["communication_anomaly"], fa=b["financial_anomaly"], nc=b["network_centrality"], sr=b["source_reliability_multiplier"])
    add(4, "LEAD", "risk_disclaimer")

    for fir in dataset["fir_records"]:
        rel = RELIABILITY_WORDS[lang].get(fir["source_reliability"], fir["source_reliability"])
        add(5, "FACT", "fir_line", case_id=fir["case_id"], station=fir["station"], date=fir["date"], rel=rel)

    add(6, "LEAD", "disclosure")
    return blocks

report_i18n = {lang: build_report(lang) for lang in LANGS}

