section_key_map = {1: "s1", 2: "s2", 3: "s3", 4: "s4", 5: "s5", 6: "s6"}
for block in report_i18n["en"]:
    if block["section"] != current_section:
        current_section = block["section"]
        flat_lines.append("")
        flat_lines.append(SECTION_TITLES["en"][section_key_map[current_section]])
        flat_lines.append("-" * 40)
    flat_lines.append(f"[{block['tag_label']}] {block['text']}")

txt_path = os.path.join(DATA_DIR, "investigation_report.txt")
with open(txt_path, "w", encoding="utf-8") as f:
    f.write("\n".join(flat_lines))
print(f"Saved English flat report -> {txt_path}")
